mapper.select:
select * from (SELECT a.INSPECTION_TASK_ID, a.INSPECTION_PLAN_ID, a.INSPECTION_TASK_YEAR, a.INSPECTION_TASK_TYPE, a.INSPECTION_TASK_NAME, a.INSPECTION_TASK_BEGINTIME, a.INSPECTION_TASK_ENDTIME, a.INSPECTION_GUOKU, a.INSPECTED_GUOKU_ID, a.INSPECTION_TASK_STATE, a.IS_LOCK_MAIN, a.IS_LOCK_GROUP, a.IS_FINISH, a.BOOKORG_ID, REPLACE(REPLACE(a.BOOKORG_DSCR,'国家金库',''),'中国人民银行','') AS BOOKORG_DSCR, a.INSPECTION_BOOKORG_ID, a.CREATE_TIME, a.UPDATE_TIME, a.CHECK_ORG, REPLACE(REPLACE(a.CHECK_ORG_DSCR,'国家金库',''),'中国人民银行','') AS CHECK_ORG_DSCR, a.CHECKED_ORG, REPLACE(REPLACE(a.CHECKED_ORG_DSCR,'国家金库',''),'中国人民银行','') AS CHECKED_ORG_DSCR, REPLACE(REPLACE(( SELECT t.guoku_dscr FROM dmcode.cm_guoku_dimnsn t WHERE a.INSPECTION_GUOKU = t.guoku_id ),'国家金库',''),'中国人民银行','') AS INSPECTION_GUOKU_DSCR, REPLACE(REPLACE(( SELECT t.guoku_dscr FROM dmcode.cm_guoku_dimnsn t WHERE a.INSPECTED_GUOKU_ID = t.guoku_id ),'国家金库',''),'中国人民银行','') AS INSPECTED_GUOKU_DSCR, ( SELECT c.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` c WHERE c.ENUM_TYPE_ID = '12' AND c.ENUM_ID = a.INSPECTION_TASK_TYPE ) AS INSPECTION_TASK_TYPE_DSCR, ( SELECT c.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` c WHERE c.ENUM_TYPE_ID = '13' AND c.ENUM_ID = a.INSPECTION_TASK_STATE ) AS IINSPECTION_TASK_STATE_DSCR, i.INSPECTION_GROUP_ID, i.INSPECTION_GROUP_NAME, p.INSPECTION_PROCESS_ID, p.INSPECTION_PROCESS_NAME, p.INSPECTION_PROCESS_SIGN, (a.IS_LOCK_MAIN + IS_LOCK_GROUP) as IS_LOCK, concat( DATE_FORMAT(a.INSPECTION_TASK_BEGINTIME, '%m-%d'), '至', DATE_FORMAT(a.INSPECTION_TASK_ENDTIME, '%m-%d') ) as TASK_TIME, n.INSPECTION_PLAN_BEGINTIME, n.INSPECTION_PLAN_ENDTIME FROM inspection.inspection_task a LEFT JOIN inspection.inspection_process p on a.INSPECTION_TASK_ID = p.INSPECTION_TASK_ID AND p.IS_ACTIVE = '0' LEFT JOIN inspection.inspection_group i on a.INSPECTION_TASK_ID = i.INSPECTION_TASK_ID LEFT JOIN inspection.inspection_plan n on a.INSPECTION_PLAN_ID = n.INSPECTION_PLAN_ID WHERE 1 = 1
AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
AND a.INSPECTION_TASK_YEAR = #{params.INSPECTION_TASK_YEAR}
AND a.INSPECTION_TASK_TYPE = #{params.INSPECTION_TASK_TYPE}
AND a.INSPECTION_TASK_NAME like '%${params.INSPECTION_TASK_NAME}%'
AND ( a.INSPECTION_GUOKU LIKE CONCAT('%',(SELECT LEFT(a.`guoku_id`,( SELECT b.level-1 FROM dmcode.`cm_guoku_dimnsn` b WHERE b.guoku_id = #{params.INSPECTION_GUOKU} )*2 ) FROM dmcode.`cm_guoku_dimnsn` a WHERE a.`guoku_id` = #{params.INSPECTION_GUOKU}),'%')
OR a.INSPECTED_GUOKU_ID LIKE CONCAT('%',(SELECT LEFT(a.`guoku_id`,( SELECT b.level-1 FROM dmcode.`cm_guoku_dimnsn` b WHERE b.guoku_id = #{params.INSPECTED_GUOKU_ID} )*2 ) FROM dmcode.`cm_guoku_dimnsn` a WHERE a.`guoku_id` = #{params.INSPECTED_GUOKU_ID}),'%')
OR a.INSPECTION_TASK_ID IN( SELECT a.`INSPECTION_TASK_ID` FROM `inspection`.`inspection_group` a LEFT JOIN `inspection`.`inspection_group_user` b ON a.`INSPECTION_GROUP_ID` = b.`INSPECTION_GROUP_ID` WHERE b.`INSPECTION_GROUP_USER` = #{params.USERID} )
)
AND a.INSPECTION_TASK_STATE = #{params.INSPECTION_TASK_STATE}
AND a.INSPECTION_TASK_BEGINTIME >= #{params.INSPECTION_TASK_BEGINTIME}
AND a.INSPECTION_TASK_ENDTIME <= #{params.INSPECTION_TASK_ENDTIME}
AND a.INSPECTION_PLAN_ID = #{params.INSPECTION_PLAN_ID}
AND a.IS_LOCK_MAIN = #{params.IS_LOCK_MAIN}
AND a.IS_LOCK_GROUP = #{params.IS_LOCK_GROUP}
AND a.BOOKORG_ID = #{params.BOOKORG_ID}
AND a.CHECK_ORG = #{params.CHECK_ORG}
AND a.CHECKED_ORG = #{params.CHECKED_ORG}
order by a.CREATE_TIME DESC, a.`INSPECTION_TASK_BEGINTIME` DESC) aa where 1=1
AND ( CHECK_ORG_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECK_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') or INSPECTION_GUOKU_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECK_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') )
AND (CHECKED_ORG_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECKED_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') or BOOKORG_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECKED_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') or INSPECTED_GUOKU_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECKED_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') )
LIMIT ${params.page},${params.rows}

select * from (SELECT a.*, ( SELECT t.guoku_dscr FROM dmcode.cm_guoku_dimnsn t WHERE a.INSPECTION_GUOKU = t.guoku_id ) AS INSPECTION_GUOKU_DSCR, ( SELECT t.guoku_dscr FROM dmcode.cm_guoku_dimnsn t WHERE a.INSPECTED_GUOKU_ID = t.guoku_id ) AS INSPECTED_GUOKU_DSCR, ( SELECT c.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` c WHERE c.ENUM_TYPE_ID = '12' AND c.ENUM_ID = a.INSPECTION_TASK_TYPE ) AS INSPECTION_TASK_TYPE_DSCR, ( SELECT c.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` c WHERE c.ENUM_TYPE_ID = '13' AND c.ENUM_ID = a.INSPECTION_TASK_STATE ) AS IINSPECTION_TASK_STATE_DSCR, i.INSPECTION_GROUP_ID, i.INSPECTION_GROUP_NAME, p.INSPECTION_PROCESS_ID, p.INSPECTION_PROCESS_NAME, p.INSPECTION_PROCESS_SIGN, (a.IS_LOCK_MAIN + IS_LOCK_GROUP) as IS_LOCK, concat(a.INSPECTION_TASK_BEGINTIME,'至',a.INSPECTION_TASK_ENDTIME) as TASK_TIME, n.INSPECTION_PLAN_BEGINTIME, n.INSPECTION_PLAN_ENDTIME FROM inspection.inspection_task a LEFT JOIN inspection.inspection_process p on a.INSPECTION_TASK_ID = p.INSPECTION_TASK_ID AND p.IS_ACTIVE = '0' LEFT JOIN inspection.inspection_group i on a.INSPECTION_TASK_ID = i.INSPECTION_TASK_ID LEFT JOIN inspection.inspection_plan n on a.INSPECTION_PLAN_ID = n.INSPECTION_PLAN_ID WHERE 1 = 1
AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
AND a.INSPECTION_TASK_YEAR = #{params.INSPECTION_TASK_YEAR}
AND a.INSPECTION_TASK_TYPE = #{params.INSPECTION_TASK_TYPE}
AND a.INSPECTION_TASK_NAME like '%${params.INSPECTION_TASK_NAME}%'
AND a.INSPECTION_GUOKU = #{params.INSPECTION_GUOKU}
AND a.INSPECTED_GUOKU_ID = #{params.INSPECTED_GUOKU_ID}
AND a.INSPECTION_TASK_STATE = #{params.INSPECTION_TASK_STATE}
AND a.INSPECTION_TASK_BEGINTIME >= #{params.INSPECTION_TASK_BEGINTIME}
AND a.INSPECTION_TASK_ENDTIME <= #{params.INSPECTION_TASK_ENDTIME}
AND a.INSPECTION_PLAN_ID = #{params.INSPECTION_PLAN_ID}
AND a.IS_LOCK_MAIN = #{params.IS_LOCK_MAIN}
AND a.IS_LOCK_GROUP = #{params.IS_LOCK_GROUP}
AND a.IS_FINISH = #{params.IS_FINISH}
AND a.CHECK_ORG = #{params.CHECK_ORG}
AND a.CHECKED_ORG = #{params.CHECKED_ORG}
order by a.CREATE_TIME DESC) aa where 1=1
AND (CHECK_ORG_DSCR like '%${params.CHECK_KEY_WORD}%' or INSPECTION_GUOKU_DSCR like '%${params.CHECK_KEY_WORD}%')
AND (CHECKED_ORG_DSCR like '%${params.CHECKED_KEY_WORD}%' or BOOKORG_DSCR like '%${params.CHECKED_KEY_WORD}%' or INSPECTED_GUOKU_DSCR like '%${params.CHECKED_KEY_WORD}%')

select count(1) from (SELECT a.*, ( SELECT t.guoku_dscr FROM dmcode.cm_guoku_dimnsn t WHERE a.INSPECTION_GUOKU = t.guoku_id ) AS INSPECTION_GUOKU_DSCR, ( SELECT t.guoku_dscr FROM dmcode.cm_guoku_dimnsn t WHERE a.INSPECTED_GUOKU_ID = t.guoku_id ) AS INSPECTED_GUOKU_DSCR, ( SELECT c.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` c WHERE c.ENUM_TYPE_ID = '12' AND c.ENUM_ID = a.INSPECTION_TASK_TYPE ) AS INSPECTION_TASK_TYPE_DSCR, ( SELECT c.ENUM_DSCR FROM `enumset`.`cm_guoku_enumeration` c WHERE c.ENUM_TYPE_ID = '13' AND c.ENUM_ID = a.INSPECTION_TASK_STATE ) AS IINSPECTION_TASK_STATE_DSCR, i.INSPECTION_GROUP_ID, i.INSPECTION_GROUP_NAME, p.INSPECTION_PROCESS_ID, p.INSPECTION_PROCESS_NAME, p.INSPECTION_PROCESS_SIGN, (a.IS_LOCK_MAIN + IS_LOCK_GROUP) as IS_LOCK, concat(a.INSPECTION_TASK_BEGINTIME,'至',a.INSPECTION_TASK_ENDTIME) as TASK_TIME, n.INSPECTION_PLAN_BEGINTIME, n.INSPECTION_PLAN_ENDTIME FROM inspection.inspection_task a LEFT JOIN inspection.inspection_process p on a.INSPECTION_TASK_ID = p.INSPECTION_TASK_ID AND p.IS_ACTIVE = '0' LEFT JOIN inspection.inspection_group i on a.INSPECTION_TASK_ID = i.INSPECTION_TASK_ID LEFT JOIN inspection.inspection_plan n on a.INSPECTION_PLAN_ID = n.INSPECTION_PLAN_ID WHERE 1 = 1
AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
AND a.INSPECTION_TASK_YEAR = #{params.INSPECTION_TASK_YEAR}
AND a.INSPECTION_TASK_TYPE = #{params.INSPECTION_TASK_TYPE}
AND a.INSPECTION_TASK_NAME like '%${params.INSPECTION_TASK_NAME}%'
AND ( a.INSPECTION_GUOKU LIKE CONCAT('%',(SELECT LEFT(a.`guoku_id`,( SELECT b.level-1 FROM dmcode.`cm_guoku_dimnsn` b WHERE b.guoku_id = #{params.INSPECTION_GUOKU} )*2 ) FROM dmcode.`cm_guoku_dimnsn` a WHERE a.`guoku_id` = #{params.INSPECTION_GUOKU}),'%')
OR
a.INSPECTED_GUOKU_ID LIKE CONCAT('%',(SELECT LEFT(a.`guoku_id`,( SELECT b.level-1 FROM dmcode.`cm_guoku_dimnsn` b WHERE b.guoku_id = #{params.INSPECTED_GUOKU_ID} )*2 ) FROM dmcode.`cm_guoku_dimnsn` a WHERE a.`guoku_id` = #{params.INSPECTED_GUOKU_ID}),'%')
OR a.INSPECTION_TASK_ID IN( SELECT a.`INSPECTION_TASK_ID` FROM `inspection`.`inspection_group` a LEFT JOIN `inspection`.`inspection_group_user` b ON a.`INSPECTION_GROUP_ID` = b.`INSPECTION_GROUP_ID` WHERE b.`INSPECTION_GROUP_USER` = #{params.USERID} )
)
AND a.INSPECTION_TASK_STATE = #{params.INSPECTION_TASK_STATE}
AND a.INSPECTION_TASK_BEGINTIME >= #{params.INSPECTION_TASK_BEGINTIME}
AND a.INSPECTION_TASK_ENDTIME <= #{params.INSPECTION_TASK_ENDTIME}
AND a.INSPECTION_PLAN_ID = #{params.INSPECTION_PLAN_ID}
AND a.IS_LOCK_MAIN = #{params.IS_LOCK_MAIN}
AND a.IS_LOCK_GROUP = #{params.IS_LOCK_GROUP}
AND a.BOOKORG_ID = #{params.BOOKORG_ID}
AND a.CHECK_ORG = #{params.CHECK_ORG}
AND a.CHECKED_ORG = #{params.CHECKED_ORG}
order by a.CREATE_TIME DESC) aa where 1=1
AND ( CHECK_ORG_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECK_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') or INSPECTION_GUOKU_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECK_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') )
AND (CHECKED_ORG_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECKED_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') or BOOKORG_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECKED_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') or INSPECTED_GUOKU_DSCR like CONCAT('%',REPLACE(REPLACE('%${params.CHECKED_KEY_WORD}%','国家金库',''),'中国人民银行',''),'%') )

mapper.update:
UPDATE inspection.inspection_task SET

    IS_LOCK_MAIN = #{params.IS_LOCK_MAIN},


    IS_LOCK_GROUP = #{params.IS_LOCK_GROUP},


    UPDATE_TIME = #{params.UPDATE_TIME},

INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
WHERE INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}

mapper.select:
SELECT * FROM inspection.inspection_task a WHERE 1 = 1 and a.INSPECTION_TASK_STATE = '1'
AND a.INSPECTION_TASK_ID != #{params.INSPECTION_TASK_ID}
AND a.INSPECTION_TASK_NAME = #{params.INSPECTION_TASK_NAME}

SELECT * FROM dmcode.cm_guoku_bookorg a WHERE 1 = 1
AND a.bookorgcode = #{params.bookorgcode}
AND a.guoku_id = #{params.guoku_id}

SELECT * FROM `dmcode`.`cm_guoku_dimnsn` a WHERE 1 = 1
AND a.bookorgcode = #{params.bookorgcode}
AND a.guoku_id = #{params.guoku_id}
